 type JwtPayload = {
   sub?: unknown;
   email?: unknown;
   name?: unknown;
   preferred_username?: unknown;
   common_name?: unknown;
 };

 function decodeBase64Url(value: string): string | null {
   try {
     const normalized = value.replace(/-/g, '+').replace(/_/g, '/');
     const padLen = (4 - (normalized.length % 4)) % 4;
     const padded = normalized + '='.repeat(padLen);
