   const parts = jwt.split('.');
   if (parts.length < 2) return null;
   const payloadText = decodeBase64Url(parts[1]);
   if (!payloadText) return null;
   try {
     return JSON.parse(payloadText) as JwtPayload;
   } catch {
     return null;
   }
